Lo scheletro Java corrispondente a una parte del diagramma, utile per controllare che le direzioni abbiano senso:

```java
import java.util.ArrayList;
import java.util.List;

class Tessera {
    private double importoCumulativo;
    private final double soglia;
    Tessera(double soglia) { this.soglia = soglia; }
    void registraAcquisto(double importo) { importoCumulativo += importo; }
    boolean haDirittoSconto() { return importoCumulativo > soglia; }   // sconto sulle transazioni successive
}

class Articolo {
    private final double prezzo;
    private int quantitaFarmacia;
    Articolo(double prezzo, int quantita) { this.prezzo = prezzo; this.quantitaFarmacia = quantita; }
    boolean isDisponibile(int qta) { return quantitaFarmacia >= qta; }
    void decrementa(int qta) { quantitaFarmacia -= qta; }
    double getPrezzo() { return prezzo; }
}

class Riga {
    final Articolo articolo; final int quantita;
    Riga(Articolo a, int q) { articolo = a; quantita = q; }
    double subtotale() { return articolo.getPrezzo() * quantita; }
}

class VenditaFarmacia {
    private static final double SCONTO = 0.10;   // valore d'esempio: il testo non lo specifica
    private final List<Riga> righe = new ArrayList<>();
    private final Tessera tessera;               // 0..1: null per cliente senza tessera
    VenditaFarmacia(Tessera tessera) { this.tessera = tessera; }
    void aggiungi(Articolo a, int qta) {
        if (!a.isDisponibile(qta)) throw new IllegalStateException("non disponibile: prenotare");
        righe.add(new Riga(a, qta));
    }
    double calcolaTotale() {
        double tot = righe.stream().mapToDouble(Riga::subtotale).sum();
        return (tessera != null && tessera.haDirittoSconto()) ? tot * (1 - SCONTO) : tot;
    }
    double conferma() {
        double totale = calcolaTotale();                       // sconto valutato PRIMA di registrare
        righe.forEach(r -> r.articolo.decrementa(r.quantita));
        if (tessera != null) tessera.registraAcquisto(totale);
        return totale;
    }
}
```

L'ordine in `conferma()` realizza esattamente il testo: lo sconto si applica alle transazioni **successive** al superamento della soglia, quindi si calcola il totale prima di aggiornare il cumulativo.

